ort {\n            height: 120px;\n            overflow-y: auto;\n            scrollbar-width: none;\n            mask-image: linear-gradient(to bottom, transparent 0%, black 20%, black 80%, transparent 100%);\n            -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 20%, black 80%, transparent 100%);\n        }\n        \n        .date-scroll-viewport::-webkit-scrollbar {\n            display: none;\n        }\n        \n        .date-scroll-item {\n            height: 40px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 18px;\n            cursor: pointer;\n        }\n        \n        .date-scroll-item:hover, .date-scroll-item.selected {\n            background-color: var(--primary-light);\n            color: var(--text-dark);\n            font-weight: bold;\n        }\n        \n        .center-marker {\n            position: absolute;\n            top: 50%;\n            left: 0;\n            right: 0;\n            height: 40px;\n            border-top: 2px solid var(--primary);\n            border-bottom: 2px solid var(--primary);\n            pointer-events: none;\n            transform: translateY(-20px);\n            opacity: 0.3;\n        }\n        \n        button {\n            background-color: var(--primary);\n            color: var(--text-light);\n            border: none;\n            padding: 15px 25px;\n            border-radius: 8px;\n            font-size: 18px;\n            cursor: pointer;\n            transition: all 0.3s;\n            display: block;\n            width: 100%;\n            font-weight: bold;\n            box-shadow: 0 4px 10px rgba(255, 119, 0, 0.3);\n        }\n        \n        button:hover {\n            background-color: var(--primary-light);\n            transform: translateY(-2px);\n        }\n        \n        .results {\n            margin-top: 30px;\n            background-color: var(--secondary);\n            padding: 