      <p>Discover interesting facts about your birthday!</p>\n        </header>\n        \n        <div class=\"content\">\n            <div class=\"date-picker\">\n                <label>Select your birth date:</label>\n                <div class=\"date-scrollers\">\n                    <div class=\"date-scroll\">\n                        <div class=\"date-scroll-title\">Month</div>\n                        <div class=\"date-scroll-viewport\" id=\"month-scroll\">\n                            <div class=\"date-scroll-item\" data-value=\"1\">January</div>\n                            <div class=\"date-scroll-item\" data-value=\"2\">February</div>\n                            <div class=\"date-scroll-item\" data-value=\"3\">March</div>\n                            <div class=\"date-scroll-item\" data-value=\"4\">April</div>\n                            <div class=\"date-scroll-item\" data-value=\"5\">May</div>\n                            <div class=\"date-scroll-item\" data-value=\"6\">June</div>\n                            <div class=\"date-scroll-item\" data-value=\"7\">July</div>\n                            <div class=\"date-scroll-item\" data-value=\"8\">August</div>\n                            <div class=\"date-scroll-item\" data-value=\"9\">September</div>\n                            <div class=\"date-scroll-item\" data-value=\"10\">October</div>\n                            <div class=\"date-scroll-item\" data-value=\"11\">November</div>\n                            <div class=\"date-scroll-item\" data-value=\"12\">December</div>\n                        </div>\n                        <div class=\"center-marker\"></div>\n                    </div>\n                    \n                    <div class=\"date-scroll\">\n                        <div class=\"date-scroll-title\">Day</div>\n                        <div class=\"date-scroll-viewport\" id=\"day-scroll\">\n                            <!-- Days will be populated based on month -->\n                        </div>\n                        <div class=\"center-marker\"></div>\n                    </div>\n                    \n                    <div class=\"date-scroll\">\n                        <div class=\"date-scroll-title\">Year</div>\n                        <div class=\"date-scroll-viewport\" id=\"year-scroll\">\n                            <!-- Years will be populated dynamically -->\n                        </div>\n                        <div class=\"center-marker\"></div>\n                    </div>\n                </div>\n            </div>\n            \n            <button id=\"calculate-btn\">Calculate Birthday Facts</button>\n            \n            <div class=\"results\" id=\"results\">\n                <h2>Your Birthday Facts</h2>\n                <div class=\"result-item\">\n                    <strong>Age:</strong> <span id=\"age-result\"></span>\n                </div>\n                <div class=\"result-item\">\n                    <strong>Days until next birthday:</strong> <span id=\"days-until-result\"></span>\n                </div>\n                <div class=\"result-item\">\n                    <strong>Day of the week you were born:</strong> <span id=\"day-of-week-result\"></span>\n                </div>\n                <div class=\"result-item\">\n                    <strong>Total days you\'ve been alive:</strong> <span id=\"days-alive-result\"></span>\n                </div>\n                <div class=\"result-item\">\n                    <strong>Zodiac Sign:</strong> <span id=\"zodiac-result\"></span>\n                </div>\n            </div>\n            \n            <div class=\"affiliate-box\" id=\"affiliate-box\">\n                <h3>Want More Birthday Insights?</h3>\n                <p>Discover your complete birthday profile and what it reveals about your personality, future, and life path!</p>\n                <a href=\"https://bit.ly/CalculatorOfBirthdates\" target=\"_blank\" class=\"affiliate-btn\">Unlock Your Full Birthday Analysis</a>\n            </div>\n        </div>\n    </div>\n    \n    <script>\n        document.addEventListener(\'DOMContentLoaded\', function() {\n            // Initialize date pickers\n            const monthScroll = document.getElementById(\'month-scroll\');\n            const dayScroll = document.getElementById(\'day-scroll\');\n            const yearScroll = document.getElementById(\'year-scroll\');\n            const calculateBtn = document.getElementById(\'calculate-btn\');\n            const resultsDiv = document.getElementById(\'results\');\n            const affiliateBox = document.getElementById(\'affiliate-box\');\n            \n            let selectedMonth = 1;\n            let selectedDay = 1;\n            let selectedYear = 2000;\n            \n            // Populate days based on month\n            function populateDays(month, year) {\n                dayScroll.innerHTML = \'\';\n                let daysInMonth = new Date(year, month, 0).getDate();\n                \n                for (let i = 1; i <= daysInMonth; i++) {\n                    const dayItem = document.createElement(\'div\');\n                    dayItem.className = \'date-scroll-item\';\n                    dayItem.textContent = i;\n                    dayItem.dataset.value = i;\n                    dayScroll.appendChild(dayItem);\n                    \n                    dayItem.addEventListener(\'click\', function() {\n                        selectedDay = parseInt(this.dataset.value);\n                        markSelected(dayScroll, selectedDay);\n                        centerScrollItem(dayScroll, this);\n                    });\n                }\n                \n                // Select first day as default\n                const firstDayItem = dayScroll.querySelector(\'.date-scroll-item\');\n                if (firstDayItem) {\n                    selectedDay = 1;\n                    markSelected(dayScroll, selectedDay);\n                }\n            }\n            \n            // Populate years (1900 to current year)\n            function populateYears() {\n                const currentYear = new Date().getFullYear();\n                \n                for (let i = currentYear; i >= 1900; i--) {\n                    const yearItem = document.createElement(\'div\');\n                    yearItem.className = \'date-scroll-item\';\n                    yearItem.textContent = i;\n                    yearItem.dataset.value = i;\n                    yearScroll.appendChild(yearItem);\n                    \n                    yearItem.addEventListener(\'click\', function() {\n                        selectedYear = parseInt(this.dataset.value);\n                        markSelected(yearScroll, selectedYear);\n                        centerScrollItem(yearScroll, this);\n                        \n                        // Update days if month is February (account for leap years)\n                        if (selectedMonth === 2) {\n                            populateDays(selectedMonth, selectedYear);\n                        }\n                    });\n                }\n                \n                // Select 2000 as default\n                selectedYear = 2000;\n                markSelected(yearScroll, selectedYear);\n                \n                // Center on 2000\n                const item2000 = yearScroll.querySelector(`[data-value=\"2000\"]`);\n                if (item2000) {\n                    centerScrollItem(yearScroll, item2000);\n                }\n            }\n            \n            // Mark selected item\n            function markSelected(container, value) {\n                container.querySelectorAll(\'.date-scroll-item\').forEach(item => {\n                    if (parseInt(item.dataset.value) === value) {\n                        item.classList.add(\'selected\');\n                    } else {\n                        item.classList.remove(\'selected\');\n                    }\n                });\n            }\n            \n            // Center scroll item\n            function centerScrollItem(container, item) {\n                if (!item) return;\n                \n                const containerHeight = container.clientHeight;\n                const itemHeight = item.clientHeight;\n                \n                container.scrollTop = item.offsetTop - (containerHeight / 2) + (itemHeight / 2);\n            }\n            \n            // Add click events to months\n            monthScroll.querySelectorAll(\'.date-scroll-item\').forEach(item => {\n                item.addEventListener(\'click\', function() {\n                    selectedMonth = parseInt(this.dataset.value);\n                    markSelected(monthScroll, selectedMonth);\n                    centerScrollItem(monthScroll, this);\n                    \n                    // Update days for the selected month\n                    populateDays(selectedMonth, selectedYear);\n                });\n            });\n            \n            // Initialize with January selected\n            markSelected(monthScroll, 1);\n            const januaryItem = monthScroll.querySelector(\'[data-value=\"1\"]\');\n            centerScrollItem(monthScroll, januaryItem);\n            \n            // Populate years and days\n            populateYears();\n            populateDays(selectedMonth, selectedYear);\n            \n            // Calculate button click\n            calculateBtn.addEventListener(\'click\', function() {\n                // Get birth date\n                const birthDate = new Date(selectedYear, selectedMonth - 1, selectedDay);\n                const today = new Date();\n                \n                // Calculate age\n                let age = today.getFullYear() - birthDate.getFullYear();\n                const monthDiff = today.getMonth() - birthDate.getMonth();\n                if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {\n                    age--;\n                }\n                \n                // Calculate days until next birthday\n                const nextBirthday = new Date(today.getFullYear(), birthDate.getMonth(), birthDate.getDate());\n                if (nextBirthday < today) {\n                    nextBirthday.setFullYear(nextBirthday.getFullYear() + 1);\n                }\n                const daysTilBirthday = Math.ceil((nextBirthday - today) / (1000 * 60 * 60 * 24));\n                \n                // Day of week\n                const daysOfWeek = [\'Sunday\', \'Monday\', \'Tuesday\', \'Wednesday\', \'Thursday\', \'Friday\', \'Saturday\'];\n                const dayOfWeek = daysOfWeek[birthDate.getDay()];\n                \n                // Days alive\n                const daysAlive = Math.floor((today - birthDate) / (1000 * 60 * 60 * 24));\n                \n                // Zodiac sign\n                const zodiacSign = getZodiacSign(selectedDay, selectedMonth);\n                \n                // Display results\n                document.getElementById(\'age-result\').textContent = age;\n                document.getElementById(\'days-until-result\').textContent = daysTilBirthday;\n                document.getElementById(\'day-of-week-result\').textContent = dayOfWeek;\n                document.getElementById(\'days-alive-result\').textContent = daysAlive.toLocaleString();\n                document.getElementById(\'zodiac-result\').textContent = zodiacSign;\n                \n                // Show results with animation\n                resultsDiv.style.display = \'block\';\n                \n                // Show affiliate box after 3 seconds\n                setTimeout(() => {\n                    affiliateBox.style.display = \'block\';\n                }, 3000);\n            });\n            \n            // Get zodiac sign\n            function getZodiacSign(day, month) {\n                const signs = [\n                    {name: \"Capricorn\", start: {month: 12, day: 22}, end: {month: 1, day: 19}},\n                    {name: \"Aquarius\", start: {month: 1, day: 20}, end: {month: 2, day: 18}},\n                    {name: \"Pisces\", start: {month: 2, day: 19}, end: {month: 3, day: 20}},\n                    {name: \"Aries\", start: {month: 3, day: 21}, end: {month: 4, day: 19}},\n                    {name: \"Taurus\", start: {month: 4, day: 20}, end: {month: 5, day: 20}},\n                    {name: \"Gemini\", start: {month: 5, day: 21}, end: {month: 6, day: 20}},\n                    {name: \"Cancer\", start: {month: 6, day: 21}, end: {month: 7, day: 22}},\n                    {name: \"Leo\", start: {month: 7, day: 23}, end: {month: 8, day: 22}},\n                    {name: \"Virgo\", start: {month: 8, day: 23}, end: {month: 9, day: 22}},\n                    {name: \"Libra\", start: {month: 9, day: 23}, end: {month: 10, day: 22}},\n                    {name: \"Scorpio\", start: {month: 10, day: 23}, end: {month: 11, day: 21}},\n                    {name: \"Sagittarius\", start: {month: 11, day: 22}, end: {month: 12, day: 21}}\n                ];\n                \n                for (let sign of signs) {\n                    if (\n                        (month === sign.start.month && day >= sign.start.day) ||\n                        (month === sign.end.month && day <= sign.end.day)\n                    ) {\n                        return sign.name;\n                    }\n                }\n                \n                return \"Capricorn\"; // Default if something goes wrong\n            }\n        });\n    </script>\n</body>\n</html>',
